kubectl delete namespace e1-t2 e1-t3 e1-t4 e1-t5 e1-apps e1-t7 e1-t8 e1-t9 e1-t10 e1-t11 e1-t12 e1-t13 e1-t14 e1-t15 --ignore-not-found
